import {GistAdapter,parseGistId} from './gist.js';
import {openWithKeys,prepareConnection} from './connect.js';
import {unsealState} from './crypto.js';
import {SyncEngine} from './engine.js';
import {loadSync,saveConnection,disconnect as clearConnection,SYNC_CONFIG_KEY,SYNC_CREDENTIAL_KEY} from './preferences.js';
export function createSyncUI({repo,icon,esc,openModal,closeModal,toast,onApply,onExport,isBlocked}){
  const saved=loadSync(localStorage);let config=saved.config,credentials=saved.credentials,engine=null,connecting=false,connectionController=null;
  let status={kind:config.gistId?'pending':'local',message:config.gistId?'Conecte com o mesmo token para conferir seus dados.':'Conecte para usar o mesmo planejamento nos seus aparelhos.'};
  const labels={local:'Não conectado',pending:'Envio pendente',syncing:'Sincronizando',confirmed:'Sincronizado',error:'Sincronização não confirmada'};
  const dateText=()=>config.confirmedAt&&Number.isFinite(Date.parse(config.confirmedAt))?'Última confirmação: '+new Date(config.confirmedAt).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'Ainda sem confirmação neste aparelho';
  function refresh(){for(const b of document.querySelectorAll('[data-sync-indicator]')){b.dataset.syncState=status.kind;b.setAttribute('aria-label','Sincronização: '+labels[status.kind]);b.title=labels[status.kind]}for(const el of document.querySelectorAll('[data-sync-label]'))el.textContent=labels[status.kind];for(const el of document.querySelectorAll('[data-sync-message]'))el.textContent=status.message;for(const el of document.querySelectorAll('[data-sync-date]'))el.textContent=dateText()}
  function setStatus(s){status=s;refresh()}
  function startEngine(){
    engine?.stop();if(!credentials||!config.gistId)return;const token=credentials.token;let legacyKey=credentials.secret!==token?credentials.secret:'';
    engine=new SyncEngine({repo,adapter:new GistAdapter(token),secret:token,gistId:config.gistId,rewriteRemote:!!legacyKey,verifyUnseal:unsealState,unseal:async text=>(await openWithKeys(text,token,legacyKey)).state,isEditing:()=>isBlocked()||document.activeElement?.matches('input,textarea,select')||!!document.querySelector('dialog[open]')||document.documentElement.classList.contains('drag-active'),isOnline:()=>navigator.onLine!==false,onState:setStatus,onApply,onConfirmed:({confirmedAt})=>{
      legacyKey='';config={...config,confirmedAt,mode:'token'};credentials={...credentials,secret:token};try{saveConnection(localStorage,{...credentials,...config})}catch{}
    },lock:navigator.locks?fn=>navigator.locks.request('entrelinhas-vida:sync:'+config.gistId,{ifAvailable:true},lock=>fn(!!lock)):null});engine.schedule(500);
  }
  function attach({gistId,token,legacySecret,remember}){config={gistId,confirmedAt:'',mode:legacySecret?'password':'token'};credentials={token,secret:legacySecret||token,remember};try{saveConnection(localStorage,{gistId,...credentials})}catch{toast('Conexão ativa nesta sessão. Não foi possível manter o token salvo neste aparelho.')}startEngine()}
  function header(){return `<button class="iconbtn sync-indicator" data-action="sync" data-sync-indicator data-sync-state="${status.kind}" aria-label="Sincronização: ${labels[status.kind]}" title="${labels[status.kind]}">${icon('cloud')}</button>`}
  function card(){return `<section class="settingscard sync-card"><div class="settings-heading"><span class="settings-icon">${icon('cloud')}</span><div><h2>Sincronização</h2><p>Seus dados no celular e no computador.</p></div><span class="sync-dot" data-sync-indicator data-sync-state="${status.kind}" aria-label="Sincronização: ${labels[status.kind]}"></span></div><div class="settings-summary"><span><strong data-sync-label>${labels[status.kind]}</strong><small data-sync-date>${esc(dateText())}</small></span><button class="btn secondary" data-action="sync">${engine?'Gerenciar conexão':'Conectar ao GitHub'}</button></div></section>`}
  function open(){
    const connected=!!engine;
    const root=openModal('Sincronização',`<div class="sync-state-banner" data-sync-indicator data-sync-state="${status.kind}">${icon('cloud')}<strong data-sync-label>${labels[status.kind]}</strong></div><div class="sync-summary"><h3>Seus dados nos dois aparelhos.</h3><p>Use o mesmo token do GitHub no celular e no computador. O backup é encontrado ou criado automaticamente.</p></div><form id="sync-form"><div class="formerror" role="alert"></div>${connected?'':`<div class="field"><label for="sync-token">Token do GitHub</label><input id="sync-token" type="password" required minlength="12" maxlength="512" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Cole seu token do GitHub" aria-describedby="sync-token-help"><small class="field-help" id="sync-token-help">Token clássico com a permissão gist.</small></div><label class="remember-choice"><input type="checkbox" id="sync-remember" checked><span>Manter conectado neste aparelho</span></label><p class="field-help">O token será guardado neste navegador se esta opção estiver marcada.</p>`}<div class="sync-main-action"><button class="btn primary full" id="connect-sync" type="submit">${connected?'Sincronizar agora':'Conectar e sincronizar'}</button></div><p class="sync-feedback" data-sync-message role="status">${esc(status.message)}</p><p class="small muted" data-sync-date>${esc(dateText())}</p>${!connected?`<details class="sync-help" id="legacy-details"><summary>Conexão anterior ou outro backup</summary><p>Se o Retomar anterior usava uma senha, informe-a uma única vez. Após a confirmação, este backup passará a usar apenas o token.</p><div class="field"><label for="sync-secret">Senha ou token anterior · opcional</label><input id="sync-secret" type="password" maxlength="1024" autocomplete="off" placeholder="Senha ou token anterior"></div><div class="field"><label for="gist-input">ID do Gist · opcional</label><input id="gist-input" autocomplete="off" placeholder="ID do backup anterior"><small class="field-help">Sem ID, será usado o backup mais recente do Retomar.</small></div></details><details class="sync-help"><summary>Como obter o token</summary><p>No GitHub, crie um token clássico e selecione a permissão <strong>gist</strong>.</p><a class="textbtn" href="https://github.com/settings/tokens" target="_blank" rel="noopener noreferrer">Abrir tokens do GitHub ${icon('arrow')}</a><p>O token também protege o backup. Guarde uma cópia: trocar o token exige a chave anterior para abrir os dados já criptografados.</p></details>`:`<details class="sync-help"><summary>Detalhes da conexão</summary><p>Use o mesmo token no outro aparelho. Não é necessário copiar o ID do backup.</p><label for="connected-gist">ID do Gist</label><input id="connected-gist" readonly value="${esc(config.gistId)}"></details>`}<p class="sync-caution">A nuvem fica verde após conferir o backup neste aparelho. Abra o aplicativo no outro aparelho para receber as alterações.</p><div class="sync-footer">${connected?'<button class="textbtn" type="button" id="sync-disconnect">Desconectar este aparelho</button>':'<button class="textbtn" type="button" id="sync-cancel">Cancelar</button>'}<button class="textbtn" type="button" id="sync-export">Baixar cópia dos dados</button></div></form>`);
    root.querySelector('#sync-export').onclick=onExport;
    root.querySelector('#sync-cancel')?.addEventListener('click',()=>closeModal(true));
    root.querySelector('#sync-disconnect')?.addEventListener('click',()=>{engine.stop();engine=null;credentials=null;config={};try{clearConnection(localStorage)}catch{toast('Não foi possível remover a configuração salva. Confira o armazenamento do navegador.')}closeModal(true);setStatus({kind:'local',message:'Desconectado neste aparelho. Seu planejamento e o backup foram preservados.'});onApply(repo.load());toast('Aparelho desconectado.');});
    root.querySelector('#sync-form').onsubmit=async e=>{
      e.preventDefault();if(connected){closeModal(true);engine?.run({manual:true});return}if(connecting)return;
      const error=root.querySelector('.formerror'),button=root.querySelector('#connect-sync'),input=root.querySelector('#sync-token');error.textContent='';input.setCustomValidity('');const token=input.value.trim();if(token.length<12||/\s/.test(token)){input.setCustomValidity('Cole um token válido do GitHub, sem espaços.');input.setAttribute('aria-invalid','true');input.checkValidity();input.focus();return}input.removeAttribute('aria-invalid');
      const remember=root.querySelector('#sync-remember').checked,legacySecret=root.querySelector('#sync-secret').value;
      connecting=true;button.disabled=true;button.textContent='Conferindo backup…';connectionController=new AbortController();const signal=connectionController.signal;
      try{const preferredId=parseGistId(root.querySelector('#gist-input').value)||config.gistId||'';const prepared=await prepareConnection({repo,adapter:new GistAdapter(token),token,preferredId,legacySecret,signal});if(signal.aborted)return;attach({...prepared,token,remember});closeModal(true);onApply(repo.load());toast(prepared.created?'Backup criado. Conferindo a sincronização.':'Backup encontrado. Conferindo a sincronização.');engine?.run({manual:true});}
      catch(err){if(signal.aborted)return;error.textContent=err.message||'Não foi possível conectar. Os dados locais foram mantidos.';if(err.code==='DECRYPT_FAILED'){root.querySelector('#legacy-details').open=true;root.querySelector('#sync-secret').focus()}}
      finally{connecting=false;button.disabled=false;button.textContent='Conectar e sincronizar'}
    };
    root.querySelector('#sync-token')?.addEventListener('input',e=>{e.target.setCustomValidity('');e.target.removeAttribute('aria-invalid')});
  }
  return {header,card,open,start(){startEngine();document.addEventListener('focusout',()=>queueMicrotask(()=>engine?.schedule(1000)));window.addEventListener('online',()=>engine?.run());window.addEventListener('storage',e=>{if(e.key===SYNC_CONFIG_KEY||e.key===SYNC_CREDENTIAL_KEY){const next=loadSync(localStorage);if(next.config.gistId!==config.gistId||JSON.stringify(next.credentials)!==JSON.stringify(credentials?.remember?credentials:null)){engine?.stop();engine=null;config=next.config;credentials=next.credentials;setStatus({kind:config.gistId?'pending':'local',message:config.gistId?'Conexão atualizada em outra aba.':'Conecte para sincronizar seus dados.'});startEngine()}}});setInterval(()=>{if(!document.hidden)engine?.run()},60000)},changed(){engine?.changed()},resume(){engine?.schedule(700)},refresh,cancelConnection(){connectionController?.abort()},hasConnection:()=>!!config.gistId};
}
